com.mirth.connect.plugins.javascriptstep.script:
var pythonPath = "C:\\Users\\Administrador\\Desktop\\Python313\\python.exe";
var scriptPath = "C:\\Users\\Administrador\\Desktop\\MIRTH\\SCRIPTS\\procesadoIMG.py";


// Guardar el JSON en un archivo
var id = msg["id"];
var tempFilePath = "C:\\Users\\Administrador\\Desktop\\MIRTH\\IMG-POST\\TEMP\\"+id+".json";

var inputMSG = JSON.stringify(msg);


var tempFile = new java.io.File(tempFilePath);
var writer = new java.io.FileWriter(tempFile);
writer.write(inputMSG);
writer.close();
logger.info(inputMSG);


var command = [
    "cmd", "/c", 
    String(pythonPath),
    String(scriptPath), 
    String(tempFilePath)
];



// Configurar y ejecutar el proceso
var process = new java.lang.ProcessBuilder(command)
    .redirectErrorStream(true)  // Redirige stderr a stdout para capturar logs de depuración
    .start();


var inputStream = process.getInputStream();
var output = '';
var bytes = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 1024);
var len;
while ((len = inputStream.read(bytes)) !== -1) {
    output += new java.lang.String(bytes, 0, len);
}
inputStream.close();

// Esperar a que el proceso termine
process.waitFor();

if (tempFile.delete()) {
    logger.info("Archivo temporal eliminado exitosamente.");
} else {
    logger.warn("No se pudo eliminar el archivo temporal.");
}
channelMap.put("idImagen", id)
msg = output.trim();

