com.mirth.connect.plugins.javascriptstep.script:
var pythonPath = "C:\\Users\\Administrador\\Desktop\\Python313\\python.exe";
var scriptPath = "C:\\Users\\Administrador\\Desktop\\MIRTH\\SCRIPTS\\citaRIS.py";

// Guardar el JSON en un archivo
var id = msg["id"];
var tempFilePath = "C:\\Users\\Administrador\\Desktop\\MIRTH\\RIS\\TEMP1\\"+id+".json";
// Convertir el mensaje de entrada a JSON (cadena)
var inputMSG = JSON.stringify(msg);


// Escribir el JSON en un archivo temporal en la ruta indicada
var tempFile = new java.io.File(tempFilePath);
var writer = new java.io.FileWriter(tempFile);
writer.write(inputMSG);
writer.close();

/*
// Configurar el comando incluyendo el archivo temporal como argumento
var command = [
    "cmd", "/c", 
    pythonPath,
    scriptPath,
    tempFilePath
];
*/
var command = java.lang.reflect.Array.newInstance(java.lang.String, 5);
command[0] = new java.lang.String("cmd");
command[1] = new java.lang.String("/c");
command[2] = new java.lang.String(pythonPath);
command[3] = new java.lang.String(scriptPath);
command[4] = new java.lang.String(tempFilePath);


// Iniciar el proceso
var process = new java.lang.ProcessBuilder(command)
    .redirectErrorStream(true)
    .start();

// Capturar la salida del proceso (STDOUT)
var output = "";
var is = process.getInputStream();
var buffer = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 1024);
var len;
while ((len = is.read(buffer)) !== -1) {
    output += new java.lang.String(buffer, 0, len);
}
is.close();
process.waitFor();

if (tempFile.delete()) {
    logger.info("Archivo temporal RIS eliminado exitosamente.");
} else {
    logger.warn("No se pudo eliminar el archivo temporal.");
}
var info = JSON.parse(output);
var imagen = info.imagen;

var dicom = JSON.parse(inputMSG);
var jsonDicom = {
    Cita: info,
    Dicom: dicom,
    Id: id
};
var dicomSalida =JSON.stringify(jsonDicom)
channelMap.put("idImagen", id);
channelMap.put("Dicom", dicomSalida);
channelMap.put("Cita", info);
channelMap.put("Informacion", inputMSG.trim());
channelMap.put("Foto", imagen.trim());

properties.script:
// Convierte la cadena JSON en un objeto a partir de 'Informacion'
var info = JSON.parse($('Informacion'));
var cita = $('Cita'); // Se asume que 'Cita' es una cadena JSON, por ejemplo: {"citaKey": "valorCita", ...}


// Accede a las propiedades de 'info'
var idPaciente = info.idPaciente;
var imagenOriginal = info.imagenOriginal;

// Crear la carpeta base para el paciente
var basePath = "C:\\Users\\Administrador\\Desktop\\PACS\\";
var folderPath = basePath + idPaciente;
var folder = new java.io.File(folderPath);

if (!folder.exists()) {
    var created = folder.mkdirs();
    if (created) {
        logger.info("Carpeta creada correctamente en: " + folderPath);
    } else {
        logger.error("No se pudo crear la carpeta en: " + folderPath);
    }
} else {
    logger.info("La carpeta ya existe en: " + folderPath);
}


var citaKey = cita.citaKey;


// Crear una subcarpeta dentro de la carpeta del paciente usando 'citaKey'
var subFolderPath = folderPath + "\\" + citaKey;
var subFolder = new java.io.File(subFolderPath);

if (!subFolder.exists()) {
    var subCreated = subFolder.mkdirs();
    if (subCreated) {
        logger.info("Subcarpeta creada correctamente en: " + subFolderPath);
    } else {
        logger.error("No se pudo crear la subcarpeta en: " + subFolderPath);
    }
} else {
    logger.info("La subcarpeta ya existe en: " + subFolderPath);
}

